PRAGMA foreign_keys = OFF;

-- Ciclo contenedor para acreditaciones externas
INSERT INTO ciclos (id, nombre, id_oficial, normativa, id_familia, id_grado) SELECT COALESCE(MAX(id), 0) + 1, 'Acreditaciones externas', 'ACREDITACIONES_EXTERNAS', NULL, NULL, NULL FROM ciclos WHERE NOT EXISTS (SELECT 1 FROM ciclos WHERE nombre = 'Acreditaciones externas');

-- Origen externo: Certificado del Ciclo Elemental de Inglés (EOI)
INSERT INTO modulos (id, nombre, id_oficial, id_ciclo) SELECT COALESCE(MAX(id), 0) + 1, 'Certificado del Ciclo Elemental de Inglés (EOI)', 'certificado_idioma', (SELECT id FROM ciclos WHERE nombre = 'Acreditaciones externas') FROM modulos WHERE NOT EXISTS (  SELECT 1 FROM modulos m   JOIN ciclos c ON c.id = m.id_ciclo   WHERE c.nombre = 'Acreditaciones externas'     AND m.nombre = 'Certificado del Ciclo Elemental de Inglés (EOI)');
INSERT INTO convalidacion (source_link, source_page, id_modulo_destino) SELECT 'https://www.boe.es/boe/dias/2020/12/30/pdfs/BOE-A-2020-17274.pdf', 124840, 35 WHERE NOT EXISTS (  SELECT 1   FROM convalidacion cv   JOIN convalidacion_origen co ON co.conv_id = cv.id   WHERE cv.id_modulo_destino = 35     AND co.id_modulo = (SELECT m.id FROM modulos m  JOIN ciclos c ON c.id = m.id_ciclo  WHERE c.nombre = 'Acreditaciones externas'    AND m.nombre = 'Certificado del Ciclo Elemental de Inglés (EOI)'  LIMIT 1));
